150	    #[test]
151	    fn a_source_restating_the_default_is_marked() {
152	        let file = Source::File(PathBuf::from("iiac-perf.md"));
153	        let same = Param::new("blocks", "100".to_string(), "100", file.clone());
154	        assert_eq!(source_cell(&same), "(iiac-perf.md, same as default)");
155	        let differs = Param::new("blocks", "50".to_string(), "100", file);
156	        assert_eq!(source_cell(&differs), "(iiac-perf.md)");
157	        let default = Param::new("blocks", "100".to_string(), "100", Source::Default);
