1	//! The `setup` command word: make a host ready for iiac-perf.
2	//!
3	//! A host was ready only after hand work, its `[freq]` steady state written into the XDG config
4	//! with the clamp limits a restore needs, and the limits are what a hand forgets (the 7600x's
5	//! declaration omitted them, and a restore there fell to 427 MHz). `setup` writes the declaration
6	//! from the live state instead.
7	//!
8	//! - **Print by default, write with `--apply`**: the plain command shows exactly what `--apply`
9	//!   would write and where, so the file is reviewed before it exists.
10	//! - **Never overwrite**: a missing file is created, a file without `[freq]` gains one at its
11	//!   end, and a file that already declares `[freq]` is left alone and checked, since it may hold
12	//!   profiles and knobs nobody wants regenerated.
13	//! - **Checked before written**: the new text must parse and pass the same steady-state checks
14	//!   every pin and restore applies, so a pinned clamp at setup time refuses rather than writing a
15	//!   pin as the steady state.
16	//! - **Run as the user**: the config belongs under the user's home, and under sudo `$HOME` may
17	//!   be root's.
18	
19	use std::io::Write;
20	use std::path::{Path, PathBuf};
21	
22	use crate::config;
23	use crate::freqctl;
24	
25	/// What `setup` does with the XDG config file.
26	#[derive(Debug, PartialEq)]
27	enum ConfigPlan {
28	    /// No file exists: create it with this text.
29	    Create { path: PathBuf, text: String },
30	    /// The file exists without `[freq]`: append this text to it, `whole` being the file after.
31	    Append {
32	        path: PathBuf,
33	        text: String,
34	        whole: String,
35	    },
36	    /// The file already declares `[freq]`: leave it, and check what it declares.
37	    Declared {
38	        path: PathBuf,
39	        config: config::Config,
40	    },
41	}
42	
43	/// The `setup` command: print the plan, and carry it out with `apply`. Exit 0 when the host is
44	/// ready (or would be, printing), 1 when a step failed or a declaration does not pass, 2 on a
45	/// refusal to run.
46	pub fn run(apply: bool) -> i32 {
47	    if is_root() {
48	        eprintln!(
49	            "error: setup: run it as your user, not under sudo: the config belongs under your \
50	             home, and $HOME under sudo may be root's"
51	        );
52	        return 2;
53	    }
54	    if config_step(apply) { 0 } else { 1 }
55	}
56	
57	/// Whether the process runs as root.
58	fn is_root() -> bool {
59	    // SAFETY: geteuid takes no arguments, cannot fail, and touches no memory.
60	    unsafe { libc::geteuid() == 0 }
61	}
62	
63	/// The config step: plan, check, print, and with `apply` write. Returns whether the host's
64	/// declaration is (or, printing, would be) one every pin and restore accepts.
65	fn config_step(apply: bool) -> bool {
66	    let path = match config::xdg_target() {
67	        Ok(Some(p)) => p,
68	        Ok(None) => {
69	            eprintln!("error: setup: neither XDG_CONFIG_HOME nor HOME is set: no config home");
70	            return false;
71	        }
72	        Err(e) => {
73	            eprintln!("error: setup: {e}");
74	            return false;
75	        }
76	    };
77	    let section = match freqctl::freq_section() {
78	        Ok(lines) => lines,
79	        Err(e) => {
80	            eprintln!("error: setup: {e}");
81	            return false;
82	        }
83	    };
84	    let existing = match std::fs::read_to_string(&path) {
85	        Ok(text) => Some(text),
86	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => None,
87	        Err(e) => {
88	            eprintln!("error: setup: reading {}: {e}", path.display());
89	            return false;
90	        }
91	    };
92	    let plan = match plan_config(&path, existing.as_deref(), &section) {
93	        Ok(p) => p,
94	        Err(e) => {
95	            eprintln!("error: setup: {e}");
96	            return false;
97	        }
98	    };
99	    match plan {
100	        ConfigPlan::Declared { path, config } => {
101	            println!("config: {} already declares [freq], left as is", path.display());
102	            match freqctl::check_steady(config.freq.as_ref()) {
103	                Ok(()) => {
104	                    println!("config: its [freq] passes every pin and restore check");
105	                    true
106	                }
107	                Err(e) => {
108	                    eprintln!("error: setup: its [freq] does not pass: {e}");
109	                    eprintln!("The live state as a [freq] section, to merge by hand:");
110	                    for line in &section {
111	                        eprintln!("  {line}");
112	                    }
113	                    false
114	                }
115	            }
116	        }
117	        ConfigPlan::Create { path, text } | ConfigPlan::Append { path, text, .. } => {
118	            let appending = existing.is_some();
119	            let whole = match &existing {
120	                Some(before) => format!("{before}{text}"),
121	                None => text.clone(),
122	            };
123	            let checked = config::parse_text(&path, &whole)
124	                .and_then(|c| freqctl::check_steady(c.freq.as_ref()));
125	            if let Err(e) = checked {
126	                eprintln!("error: setup: the live state does not make a declaration: {e}");
127	                return false;
128	            }
129	            let verb = match (apply, appending) {
130	                (false, false) => "would create",
131	                (false, true) => "would append to",
132	                (true, false) => "creating",
133	                (true, true) => "appending to",
134	            };
135	            println!("config: {verb} {}:", path.display());
136	            println!();
137	            print!("{text}");
138	            println!();
139	            if !apply {
140	                println!("config: rerun with --apply to write it");
141	                return true;
142	            }
143	            match write_config(&path, &text, appending) {
144	                Ok(()) => {
145	                    println!("config: wrote {}", path.display());
146	                    true
147	                }
148	                Err(e) => {
